-- A profile's starred items. created_at is when it was starred, as the
-- device that starred it knows it; the earliest star of an item stays.
-- Synced; its triggers are generated by internal/replica.

CREATE TABLE favorite (
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (account_id, item_id)
);

CREATE INDEX favorite_item ON favorite(item_id);
CREATE INDEX favorite_recent ON favorite(account_id, created_at);
CREATE INDEX favorite_sync ON favorite(sync_version);
